import math, re, itertools, humanize as h

DIGITS = re.compile(r"\d+\.\d+|\d+")
SUP = str.maketrans("⁰¹²³⁴⁵⁶⁷⁸⁹⁻", "0123456789-")

def sigfigs(s):
    m = DIGITS.search(s)
    if not m: return None
    t = m.group(0).replace(".", "")
    return len(t.lstrip("0")) or 1

problems = []
mants = [1.0, 9.996, 9.9996, 99.996, 99.9996, 999.6, 999.96, 1.005, 9.995, 1.2345, 5.0]
for e, m_, p, unit in itertools.product(range(-34, 35), mants, range(0, 8), ("", "W")):
    v = m_ * 10**e
    if v == 0: continue
    try:
        out = h.metric(v, unit, p)
    except Exception as ex:
        problems.append(("crash", v, p, unit, repr(ex))); continue
    if "x 10" in out:
        exp_e = int(out.split("x 10")[1].translate(SUP))
        mant = float(out.split(" x ")[0])
        tol = 0.51 * 10**(exp_e - p + 1) if p >= 1 else 5e10
        if abs(mant * 10**exp_e - v) > max(tol, abs(v) * 6e-4):
            problems.append(("sci-mismatch", v, p, out))
        continue
    s = sigfigs(out)
    if s is None:
        problems.append(("no-digits", v, p, out)); continue
    if p > 0 and s > p:
        problems.append(("too-many-digits", v, p, out, s))
    if out[0] == "-": continue
    prefixes = {"k":3,"M":6,"G":9,"T":12,"P":15,"E":18,"Z":21,"Y":24,"R":27,"Q":30,
                "m":-3,"μ":-6,"n":-9,"p":-12,"f":-15,"a":-18,"z":-21,"y":-24,"r":-27,"q":-30}
    shift = 0
    body = out[: -len(unit)] if unit else out
    for ch, sh in prefixes.items():
        if body.rstrip().endswith(ch) and not body.rstrip()[-len(ch)-1:len(body.rstrip())-len(ch)].isdigit() if False else False:
            pass
    # simpler: strip unit, then check last non-space char(s) against prefixes
    b = (out[:-len(unit)] if unit else out).rstrip()
    for ch, sh in sorted(prefixes.items(), key=lambda kv: -len(kv[0])):
        if b.endswith(ch):
            shift = sh; b = b[: -len(ch)].rstrip(); break
    num = float(DIGITS.search(b).group(0))
    approx = num * 10**shift
    ulp = 0.51 * 10**(math.floor(math.log10(v)) - p + 1) if p >= 1 else 5e10
    if abs(approx - v) > ulp + 1e-9:
        problems.append(("value-drift", v, p, out, approx))

print("cases:", 69 * len(mants) * 8 * 2, "problems:", len(problems))
for x in problems[:30]: print(x)
PY"}

