from math import log
from humanize.filesize import suffixes

def old(value, binary=False, gnu=False, format='%.1f'):
    suffix = suffixes['gnu'] if gnu else (suffixes['binary'] if binary else suffixes['decimal'])
    base = 1024 if (gnu or binary) else 1000
    b = float(value); ab = abs(b)
    if ab == 1 and not gnu: return '%d Byte' % int(b)
    if ab < base: return f'{int(b)}B' if gnu else '%d Bytes' % int(b)
    exp = int(min(log(ab, base), len(suffix)))
    mag = b / base**exp
    return (format % mag) + ('' if gnu else ' ') + suffix[exp-1]

from humanize import naturalsize
import itertools, random
vals = [999_960, 999_980_000, 1024**3-1, 1024**2-1, 10**6-40, 1024**11-40, 10**34*3, 1024**10-40,
        1023999999999999999999999999999999960, 1024**10*1024-40, -999_960, 1536, 1024, 1024**2+500]
for v in vals:
