    dead = [i for i,x in enumerate(items) if x is _MISSING]
    cov = set()
    for a,b in ded: cov.update(range(a,b))
    out = []
    if cov != set(dead): out.append(f'{tag}: ded {ded} != dead {dead}')
    if items and items[-1] is _MISSING: out.append(f'{tag}: dead suffix remains, ded={ded}, len={len(items)}')
    if any(b > len(items) for a,b in ded): out.append(f'{tag}: stale {ded} len={len(items)}')
    if list(s) != ref: out.append(f'{tag}: iter {list(s)} != {ref}')
    for i in range(len(ref)):
        if s[i] != ref[i]: out.append(f'{tag}: s[{i}]={s[i]} want {ref[i]}')
        if s[-len(ref)+i] != ref[i]: out.append(f'{tag}: s[-{len(ref)-i}]={s[-len(ref)+i]} want {ref[i]}')
    return out

