from boltons.setutils import IndexedSet, _MISSING
import random, itertools

def full_check(s, ref, tag, errs):
    # invariants
    items, ded = s.item_list, s.dead_indices
    dead = set(i for i,x in enumerate(items) if x is _MISSING)
    cov = set()
    for a,b in ded: cov.update(range(a,b))
    if cov != dead: errs.append(f'{tag}: ded {ded} vs dead {dead}')
    if items and items[-1] is _MISSING: errs.append(f'{tag}: dead suffix left {ded} len={len(items)}')
    if any(b > len(items) for a,b in ded): errs.append(f'{tag}: stale {ded} len={len(items)}')
    if list(s) != ref: errs.append(f'{tag}: iter {list(s)} != {ref}')
    # fresh comparison
    fresh = IndexedSet(ref)
    n = len(ref)
    # every index in range + out of range
    for i in range(-n, n) if n else []:
        if s[i] != ref[i]: errs.append(f'{tag}: s[{i}]={s[i]} != {ref[i]}')
        if s[i] != fresh[i]: errs.append(f'{tag}: s[{i}] != fresh[{i}]')
    for bad in ([n, -n-1] if n else [0, -1, 5, -5]):
        try: s[bad]; errs.append(f'{tag}: s[{bad}] no raise')
        except IndexError: pass
    # slices: sample
    if n:
        for a,b,c in itertools.product([None,0,1,-1,n//2,-n,n+3,-n-3],[None,0,-1,n,-n,n+2],[None,1,2,-1,-2]):
            sl = slice(a,b,c)
            g, f = list(s[sl]), list(fresh[sl])
            if g != f: errs.append(f'{tag}: slice {sl} {g} != fresh {f}')
            if c is None or c > 0:
                if g != ref[sl]: errs.append(f'{tag}: slice {sl} {g} != list {ref[sl]}')

errs = []
random.seed(2024)
for trial in range(150):
    n0 = random.randint(1, 60)
    s = IndexedSet(range(n0)); ref = list(range(n0))
    ops = []
    for step in range(random.randint(20, 80)):
        choices = ['rm','rm','add','pop','idx','slice','reverse','discard','index']
        op = random.choice(choices)
        try:
            if op == 'rm' and ref:
                i = random.randrange(len(ref)); v = ref.pop(i); s.remove(v); ops.append(('rm',v))
            elif op == 'discard' and ref:
                i = random.randrange(len(ref)); v = ref.pop(i); s.discard(v); ops.append(('dis',v))
            elif op == 'add':
                v = random.randint(-5, n0+5); s.add(v)
                if v not in ref: ref.append(v)
                ops.append(('add',v))
            elif op == 'pop' and ref:
                i = random.randrange(-len(ref), len(ref))
                v = s.pop(i); w = ref.pop(i)
                if v != w: errs.append(f't{trial}: pop({i}) {v} != {w} ops={ops}')
                ops.append(('pop',i))
            elif op == 'idx' and ref:
                i = random.randrange(len(ref))
                if s[i] != ref[i]: errs.append(f't{trial}: s[{i}] ops={ops}')
            elif op == 'slice' and ref:
                a = random.choice([None, random.randint(-len(ref)-3, len(ref)+3)])
