    allows.set(r, s)
  }
  const out = []
  for (const a of ranges) for (const b of ranges) {
    const A = allows.get(a), B = allows.get(b)
    let witness = null
    for (const v of versions) if (A.has(v) && !B.has(v)) { witness = v; break }
    let got
    try { got = subset(a, b, opts) } catch (e) { got = 'THROW' }
    const expect = !witness
    if (got !== expect) out.push([opts?'ip':'', a, b, 'got='+got, witness ? 'witness='+witness : 'NO-WITNESS'])
