from pathlib import Path
p = Path("internal/re.js")
s = p.read_text()
old = """// ## Pre-release Version Identifier
// A numeric identifier, or a non-numeric identifier.

createToken('PRERELEASEIDENTIFIER', `(?:${src[t.NUMERICIDENTIFIER]
}|${src[t.NONNUMERICIDENTIFIER]})`)
"""
new = """// ## Pre-release Version Identifier
// A non-numeric identifier, or a numeric identifier.
// The non-numeric alternative must be tried first: it always consumes a
// whole dot-separated identifier, whereas the numeric alternative can
// stop early (e.g. '7' of '7f3c').  Anchored uses of the prerelease
// regex would backtrack to the longer match, but unanchored consumers
// such as COERCEFULL would keep the truncated one.

createToken('PRERELEASEIDENTIFIER', `(?:${src[t.NONNUMERICIDENTIFIER]
}|${src[t.NUMERICIDENTIFIER]})`)
"""
assert s.count(old) == 1, s.count(old)
p.write_text(s.replace(old, new))
print("patched")
