const path = require('path')
const repo = path.join(__dirname, '..', 'work', 'repo')
const { src, t } = require(path.join(repo, 'internal', 're.js'))
const parse = require(path.join(repo, 'functions', 'parse.js'))

const idOld = '(?:0|[1-9]\\d*|\\d*[a-zA-Z-][a-zA-Z0-9-]*)'
const idNew = '(?:\\d*[a-zA-Z-][a-zA-Z0-9-]*|0|[1-9]\\d*)'
const pre = (id) => `(?:-(${id}(?:\\.${id})*))?`
const mk = (id) => new RegExp(src[t.COERCEPLAIN] + pre(id) + `(?:${src[t.BUILD]})?` + '(?:$|[^\\d])')
const A = mk(idOld)
const B = mk(idNew)

// emulate coerce() end-to-end for a given regex
const coerceWith = (re, version, opts) => {
  const match = version.match(re)
  if (!match) return null
  const major = match[2]
  const minor = match[3] || '0'
  const patch = match[4] || '0'
  const prerelease = opts.includePrerelease && match[5] ? `-${match[5]}` : ''
  const build = opts.includePrerelease && match[6] ? `+${match[6]}` : ''
  return parse(`${major}.${minor}.${patch}${prerelease}${build}`, opts)
}

const words = ['7f3c', '4821', '9e1d', 'rc', 'alpha', 'a7f3', '0', '1', '12', 'x', 'nightly', 'sha', '0a', 'a0', 'a-b', '1a2', '2b3', '01', '-x']
const pick = (n) => {
  let s = ''
  for (let i = 0; i < n; i++) s += words[Math.floor(Math.random() * words.length)] + (Math.random() < 0.6 ? '.' : '')
  return s.replace(/\.$/, '') || '0'
}

let worse = 0, better = 0, total = 0
const worseSamples = []
for (let i = 0; i < 40000; i++) {
  let v = `${Math.floor(Math.random() * 100)}.${Math.floor(Math.random() * 100)}.${Math.floor(Math.random() * 100)}`
  if (Math.random() < 0.7) v += '-' + pick(1 + Math.floor(Math.random() * 3))
  if (Math.random() < 0.3) v += '+' + pick(1 + Math.floor(Math.random() * 2))
  v = ['v', '=', '', ''][Math.floor(Math.random() * 4)] + v
  if (Math.random() < 0.3) v = 'x ' + v
  if (Math.random() < 0.2) v = v + ' tail'
  const opts = { includePrerelease: true }
  const ra = coerceWith(A, v, opts)
  const rb = coerceWith(B, v, opts)
  total++
  const sa = ra ? `${ra.version}+${ra.build}` : null
  const sb = rb ? `${rb.version}+${rb.build}` : null
  if (sa === sb) continue
  // compare old vs new: new is "worse" if it is null or strictly less informative
  if (!rb || (ra && !rb)) {
    worse++
    if (worseSamples.length < 10) worseSamples.push([v, sa, sb])
  } else if (ra && rb && sa.startsWith(sb) === false && sb.startsWith(sa) === false) {
    // neither is a prefix of the other - flag for manual look
    worse++
    if (worseSamples.length < 10) worseSamples.push([v, sa, sb, 'divergent'])
  } else {
    better++
  }
}
for (const s of worseSamples) console.log('CHECK', JSON.stringify(s))
console.log({ total, better, worse })
