// Reconstruct pre-fix coerce behavior in-tree by building COERCEFULL/COERCERTLFULL
// with the OLD prerelease-identifier order, using the same rtl loop as functions/coerce.js
const path = require('path')
const repo = path.join(__dirname, '..', 'work', 'repo')
const { src, t } = require(path.join(repo, 'internal', 're.js'))
const parse = require(path.join(repo, 'functions', 'parse.js'))

const idOld = '(?:0|[1-9]\\d*|\\d*[a-zA-Z-][a-zA-Z0-9-]*)'
const pre = `(?:-(${idOld}(?:\\.${idOld})*))?`
const COERCEFULL_OLD = new RegExp(src[t.COERCEPLAIN] + pre + `(?:${src[t.BUILD]})?` + '(?:$|[^\\d])')
const COERCERTLFULL_OLD = new RegExp(COERCEFULL_OLD.source, 'g')

const coerceOld = (version, options) => {
  options = options || {}
  let match = null
  if (!options.rtl) {
    match = version.match(COERCEFULL_OLD)
  } else {
    const coerceRtlRegex = COERCERTLFULL_OLD
    let next
    while ((next = coerceRtlRegex.exec(version)) &&
        (!match || match.index + match[0].length !== version.length)) {
      if (!match ||
            next.index + next[0].length !== match.index + match[0].length) {
        match = next
      }
      coerceRtlRegex.lastIndex = next.index + next[1].length + next[2].length
    }
    coerceRtlRegex.lastIndex = -1
