{"intent":"Brute-force invariant check: numeric part must be below base unless largest unit","command":"cd work/repo && PYTHONPATH=src python3 -c "
import re, math
from humanize import naturalsize
from humanize.filesize import suffixes

pat = re.compile(r'^(-?[0-9.]+)\s?([A-Za-z]+)$')

def check(v, mode, fmt='%.1f'):
    kw = {}
    if mode=='binary': kw['binary']=True
    if mode=='gnu': kw['gnu']=True
    out = naturalsize(v, format=fmt, **kw)
    m = pat.match(out)
    if not m: return ('unparsed', out)
    num = float(m.group(1)); sfx = m.group(2)
    suf = suffixes[mode]
    base = 1024 if mode in ('binary','gnu') else 1000
    idx = suf.index(sfx) if isinstance(suf, tuple) else suf.index(sfx)
    largest = (idx == len(suf)-1)
    if not largest and abs(num) >= base:
        return ('num>=base', out, num, sfx)
    return None

problems=[]
for mode in ('decimal','binary','gnu'):
    base = 1024 if mode in ('binary','gnu') else 1000
    for exp in range(1, 11):
        b = base**exp
        vals = [b-1, b-2, int(b*0.9995), int(b-1)//2, b, b+1, int(b*1.0004)]
        for v in vals:
            if v < base: continue
            for fmt in ('%.1f','%.0f','%.2f','%.3f','%d','%g','%.1e','%+.1f'):
                r = check(v, mode, fmt)
                if r: problems.append((v, mode, fmt, r))
print('problems:', len(problems))
for p in problems[:40]: print(p)
""}

