import random, re
from humanize import naturalsize
from humanize.filesize import suffixes

random.seed(42)
fails=[]
def fuzz(v, mode, fmt):
    kw={}
    if mode=='binary': kw['binary']=True
    if mode=='gnu': kw['gnu']=True
    base = 1024 if mode in ('binary','gnu') else 1000
    out = naturalsize(v, format=fmt, **kw)
    suf = suffixes[mode]
    idx=None
    for i,s in enumerate(suf):
        if s in out: idx=i
    if idx is None: return
    numstr = out.replace(suf[idx],'').strip().replace('+','')
    try: n=float(numstr)
    except ValueError: return
    unit = base**(idx+1)
    # round value as the bug reporter expects
    try: out2 = naturalsize(n*unit, format=fmt, **kw)
    except Exception as e: out2 = 'EXC:'+str(e)
    if out2 != out:
        fails.append((v, mode, fmt, out, out2))

for mode in ('decimal','binary','gnu'):
    base = 1024 if mode in ('binary','gnu') else 1000
    for exp in range(1,11):
        b = base**exp
        # dense sampling just under the boundary + random values in unit
        cands = [b-1, b-2, b-3, int(b*0.99995), int(b*0.9999995), int(b*0.9995),
                 b - b//1000, b//2 + b//2000, b//2]
        cands += [random.randrange(b//base, b) for _ in range(30)]
        for v in cands:
            if v < base or v > 10**40: continue
            for fmt in ('%.1f','%.0f','%.2f','%.3f','%d','%g'):
                for val in (v,-v):
                    fuzz(val, mode, fmt)
print('roundtrip failures:', len(fails))
seen=set()
for f in fails:
    key=(f[1],f[2])
    if key in seen: continue
    seen.add(key); print(f)
