# Brute-force: simulate the new round-robin loop and compare outputs
# against builtin zip for many length combinations, strict on/off.
import itertools

def simulate(lens, strict):
    iters = [iter(range(n)) for n in lens]
    count = len(iters)
    out = []
    pulls = [0]*count
    while True:
        values = [None]*count
        exhausted = set()
        for j, it in enumerate(iters):
            pulls[j] += 1
            try:
                values[j] = next(it)
            except StopIteration:
                exhausted.add(j)
        if not exhausted:
            out.append(tuple(values))
            continue
        if strict and len(exhausted) < count:
            return out, 'ValueError', pulls
        return out, 'stop', pulls

def zip_ref(lens, strict):
    iters = [iter(range(n)) for n in lens]
    pulls = [0]*len(iters)
    class Track:
        def __init__(self, it, i): self.it, self.i = it, i
        def __iter__(self): return self
        def __next__(self):
            pulls[self.i] += 1
            return next(self.it)
    tracked = [Track(it, i) for i, it in enumerate(iters)]
    out = []
    try:
        for t in zip(*tracked, strict=strict):
            out.append(tuple(pulls_i for pulls_i in ()))
            out[-1] = None
    except ValueError:
        return out, 'ValueError', pulls
    return out, 'stop', pulls

mismatch = 0
