                try:
                    yielded[next(g)] += 1
                except StopIteration:
                    pass
        elif r < 0.85:
            # interleave a full iteration while generators suspended
            list(b)
        else:
            # advance some suspended generator
            if gens:
                k, g = random.choice(gens)
                try:
                    yielded.update(islice(g, random.randint(1, 3)))
                except RuntimeError:
                    pass

    # final drain: for each key, consume everything; also finish suspended generators
    for k, g in gens:
