// Ground truth: subset(a,b) should be true iff every version satisfying a also satisfies b
const semver = require('./repo/index.js')

const PRE = ['', '-0', '-alpha.1', '-beta.2', '-rc.0', '-rc.1', '-rc.3', '-rc.4', '-rc.5', '-rc.6', '-rc.7']
