for (const M of [0, 1, 2, 3, 6, 7, 9]) {
  for (const m of [0, 1, 2, 3]) {
    for (const p of [0, 1]) {
      for (const pre of PRE) versions.add(`${M}.${m}.${p}${pre}`)
