  }
}
const UNIVERSE = [...versions].filter(v => semver.valid(v))

function truth (sub, dom, options = {}) {
  for (const v of UNIVERSE) {
    if (semver.satisfies(v, sub, options) && !semver.satisfies(v, dom, options)) {
      return false
    }
  }
  return true
}

module.exports = { truth, UNIVERSE }
